CREATE COLUMN TABLE "TEST_AP"."AFML" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(20) NOT NULL , "Descr" NVARCHAR(100), "SttId" INTEGER CS_INT, "FmlLang" NCLOB MEMORY THRESHOLD 1000, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "FmlType" NVARCHAR(1) DEFAULT 'T' NOT NULL , "IsOrigFml" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("AbsId", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AFML_CODE" ON "TEST_AP"."AFML" ( "FmlType" ASC, "Code" ASC, "LogInstanc" ASC )